// # ------------------------------------------------------------------------------
// # Reboots the machine after ~150us
// # See:
// #   https://github.com/torvalds/linux/blob/366a4e38b8d0d3e8c7673ab5c1b5e76bbfbc0085/drivers/firmware/raspberrypi.c#L249-L257
// #   https://github.com/torvalds/linux/blob/366a4e38b8d0d3e8c7673ab5c1b5e76bbfbc0085/drivers/watchdog/bcm2835_wdt.c#L100-L123
// # ------------------------------------------------------------------------------
// .align 2
// reboot:
// .if       UART_DEBUG
//   adr     x0, msg_rebooting
//   mov     x1, #48
//   mov     x2, #59
//   mov     x3, #0x00ffffff
//   mov     x4, #0x00ff0000
//   bl      paint_string
// .endif
//   mov     x0, #0x8000000
//   bl      wait_cycles
//   adr     x0, mbox_reboot
//   bl      mbox_call
//   adrp    x0, #0x3f100000                         // x0 = PM_BASE
//   mov     w1, #0x5a000000                         // w1 = PM_PASSWORD
//   orr     w2, w1, 0x0a                            // w2 = PM_PASSWORD | 10 (=> 10 ticks ~150us)
//   str     w2, [x0, #0x24]                         // [PM_WDOG] = [0x3f100024] = 0x5a00000a
//   ldr     w3, [x0, #0x1c]                         // w3 = [PM_RSTC] = [0x3f10001c]
//   and     w3, w3, #0xffffffcf                     // w3 &= PM_RSTC_WRCFG_CLR (clear bits 4, 5)
//   orr     w3, w3, w1                              // w3 |= 0x5a000000 (PM_PASSWORD)
//   orr     w3, w3, #0x00000020                     // set bit 5 (PM_RSTC_WRCFG_FULL_RESET)
//   str     w3, [x0, #0x1c]                         // [0x3f10001c] = ([0x3f10001c] & 0xffffffcf) | 0x5a000020
// # msr     daifset, #2
//   b       sleep
//
//
// # Memory block for GPU mailbox call to advise of incoming reboot
// .align 4
// mbox_reboot:
//   .word (mbox_reboot_end-mbox_reboot)             // Buffer size = 24 = 0x18
//   .word 0                                         // Request/response code
//   .word 0x00030048                                // Tag 0 - RPI_FIRMWARE_NOTIFY_REBOOT
//   .word 0                                         //   value buffer size
//   .word 0                                         //   request: should be 0          response: 0x80000000 (success) / 0x80000001 (failure)
//   .word 0                                         // End Tags
// mbox_reboot_end:
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text


// On entry:
//   w0 = colour to paint border
.align 2
// ------------------------------------------------------------------------------
// Paint the four border rectangles around the screen edge
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
paint_border:
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
  stp     x19, x20, [sp, #-16]!                   // Push x19, x20 on the stack so x19 can be used in this function.
  mov     w19, w0                                 // w19 = w0 (colour to paint border)
  mov     w0, 0                                   // Paint rectangle from 0,0 (top left of screen) with width
  mov     w1, 0                                   // SCREEN_WIDTH and height BORDER_TOP in colour w19 (border colour).
  mov     w2, SCREEN_WIDTH                        // This is the border across the top of the screen.
  mov     w3, BORDER_TOP
  mov     w4, w19
  bl      paint_rectangle
  mov     w0, 0                                   // Paint left border in border colour. This starts below the top
  mov     w1, BORDER_TOP                          // border (0, BORDER_TOP) and is BORDER_LEFT wide and stops above
  mov     w2, BORDER_LEFT                         // the bottom border (drawn later in function).
  mov     w3, SCREEN_HEIGHT-BORDER_TOP-BORDER_BOTTOM
  mov     w4, w19
  bl      paint_rectangle
  mov     w0, SCREEN_WIDTH-BORDER_RIGHT           // Paint the right border in border colour. This also starts below
  mov     w1, BORDER_TOP                          // the top border, but on the right of the screen, and is
  mov     w2, BORDER_RIGHT                        // BORDER_RIGHT wide. It also stops immediately above bottom border.
  mov     w3, SCREEN_HEIGHT-BORDER_TOP-BORDER_BOTTOM
  mov     w4, w19
  bl      paint_rectangle
  mov     w0, 0                                   // Paint the bottom border in border colour. This is BORDER_BOTTOM
  mov     w1, SCREEN_HEIGHT-BORDER_BOTTOM         // high, and is as wide as the screen.
  mov     w2, SCREEN_WIDTH
  mov     w3, BORDER_BOTTOM
  mov     w4, w19
  bl      paint_rectangle
  ldp     x19, x20, [sp], #0x10                   // Restore x19 so no calling function is affected.
  ldp     x29, x30, [sp], #0x10                   // Pop frame pointer, procedure link register off stack.
  ret


// ------------------------------------------------------------------------------
// Fill a solid rectangle in the framebuffer at the given coordinates
// ------------------------------------------------------------------------------
// On entry:
//   w0 = x
//   w1 = y
//   w2 = width (pixels)
//   w3 = height (pixels)
//   w4 = colour
// On exit:
//   TODO
paint_rectangle:
  adr     x9, fb_req                              // x9 = address of mailbox request.
  ldr     w10, [x9, framebuffer-fb_req]           // w10 = physical address of framebuffer
  orr     x10, x10, #0xfffffff000000000           // x10 = virtual address of framebuffer
  ldr     w11, [x9, pitch-fb_req]                 // w11 = pitch
  umaddl  x10, w1, w11, x10                       // x10 = address of framebuffer + y*pitch
  add     x10, x10, x0, lsl #2                    // x10 = address of framebuffer + y*pitch + x*4
  1:                                              // Fills entire rectangle
    mov     x12, x10                              // x12 = reference to start of line
    mov     w13, w2                               // w13 = width of line
    2:                                            // Fill a single row of the rectangle with colour.
      str     w4, [x10], 4                        // Colour current point, and update x10 to next point.
      subs    w13, w13, 1                         // Decrease horizontal pixel counter.
      b.ne    2b                                  // Repeat until line complete.
    add     x10, x12, x11                         // x10 = start of current line + pitch = start of new line.
    subs    w3, w3, 1                             // Decrease vertical pixel counter.
    b.ne    1b                                    // Repeat until all framebuffer lines complete.
  ret


// ------------------------------------------------------------------------------
// Paint the main screen area inside the border
// ------------------------------------------------------------------------------
// On entry:
//   w0 = colour to paint main screen
// On exit:
//   TODO
paint_window:
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
  mov     w4, w0                                  // Paint a single rectange that fills the gap inside the
  mov     w0, BORDER_LEFT                         // four borders of the screen.
  mov     w1, BORDER_TOP
  mov     w2, SCREEN_WIDTH-BORDER_LEFT-BORDER_RIGHT
  mov     w3, SCREEN_HEIGHT-BORDER_TOP-BORDER_BOTTOM
  bl      paint_rectangle
  ldp     x29, x30, [sp], #0x10                   // Pop frame pointer, procedure link register off stack.
  ret


// ------------------------------------------------------------------------------
// Converts a uint64 value to ASCII decimal representation. The caller must
// provide a buffer of at least 21 bytes. The result will be written to the end of
// the buffer, including a trailing 0 byte. The start address will be returned.
// The generated decimal string has no left padding with 0's or spaces etc.
// ------------------------------------------------------------------------------
// On entry:
//   x0 = address of 21 (or more) byte buffer to write to
//   x2 = value to convert to decimal
// On exit:
//   x0 = address of start of string within buffer
//   x1 = first char (byte) of generated string (e.g. 48-57 for '0'-'9', _not_ the address)
//   x2 = 0
//   x3 = 0xcccccccccccccccd
//   x4 = 0
base10:
  add     x0, x0, #0x14                           // x0 = address of last allocated byte
  strb    wzr, [x0]                               // Store 0 in last allocated byte
  mov     x3, #0xcccccccccccccccc
  add     x3, x3, #1                              // x3 = constant for divison by 10
  1:
    umulh   x4, x3, x2
    lsr     x4, x4, #3                            // x4 = x2 / 10
    add     x1, x4, x4, lsl #2                    // x1 = 5 * x4
    sub     x2, x2, x1, lsl #1                    // x2 = x2 % 10 = value of last digit
    add     x1, x2, #0x30                         // x1 = ASCII value of digit = x2 + 48
    strb    w1, [x0, #-1]!                        // store ASCII value on stack at correct offset
    mov     x2, x4                                // x2 = previous x2 / 10
    cbnz    x2, 1b                                // if x2 != 0 continue looping
3:
  ret




// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


// These bcm283x hardware random number generator routines are inspired by:
//   https://github.com/torvalds/linux/blob/d4f6d923238dbdb69b8525e043fedef2670d4f2c/drivers/char/hw_random/bcm2835-rng.c
// Note: RNG registers are not documented in BCM2711/BCM2837 peripherals datasheets.
// The Linux kernel source above is the only available reference for the register layout.


.text


.align 2
// ------------------------------------------------------------------------------
// Initialise BCM2835/2837 hardware random number generator
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
rand_init_bcm283x:
  mov     x5, x30
  adrp    x1, 0x3f104000 + _start
  mov     w0, #0x00100000                         // "warmup count": the initial numbers generated are "less random" so will be discarded
                                                  // set this higher than in linux kernel, as results seem better with higher value
  str     w0, [x1, #0x4]                          // [0x3f104004] = 0x00100000
  ldr     w0, [x1, #0x10]
  orr     w0, w0, #0x01
  str     w0, [x1, #0x10]                         // Set bit 0 of [0x3f104010]  (mask the interrupt)
  ldr     w0, [x1]
  orr     w0, w0, #0x01
  str     w0, [x1]                                // Set bit 0 of [0x3f104000]  (enable the hardware generator)
  ret     x5


// ------------------------------------------------------------------------------
// Return 64 bits of random data in x0 from BCM2835/2837 RNG
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
rand_x0_bcm283x:
  adrp    x1, 0x3f104000 + _start
  1:                                              // Wait until ([0x3f104004] >> 24) >= 1
    ldr     w0, [x1, #0x4]                        // Bits 24-31 tell us how many words
    lsr     w0, w0, #24                           // are available.
    cbz     w0, 1b                                // Try again if no words are available.
  ldr     w2, [x1, #0x8]                          // w2 = [0x3f104008] (random data)
  1:                                              // Wait until ([0x3f104004] >> 24) >= 1
    ldr     w0, [x1, #0x4]                        // Bits 24-31 tell us how many words
    lsr     w0, w0, #24                           // are available.
    cbz     w0, 1b                                // Try again if no words are available.
  ldr     w0, [x1, #0x8]                          // w0 = [0x3f104008] (random data)
  bfi     x0, x2, #32, #32                        // Copy bits from w2 into high bits of x0.
  ret


// ------------------------------------------------------------------------------
// Write random data to a buffer.
// ------------------------------------------------------------------------------
// On entry:
//   x0 = address of buffer (4 byte aligned)
//   x1 = size of buffer (multiple of 4 bytes)
// On exit:
//   x0 = first address after buffer
//   x1 = 0
//   x2 = 0x3f104000
//   x3 = last random word written to buffer
rand_block_bcm283x:
  and     x0, x0, #~0b11
  and     x1, x1, #~0b11
  adrp    x2, 0x3f104000 + _start
  1:                                              // Loop until buffer filled
    2:                                            // Wait until ([0x3f104004] >> 24) >= 1
      ldr     w3, [x2, #0x4]                      // Since bits 24-31 tell us how many words
      lsr     w3, w3, #24                         // are available, this must be at least one.
      cbz     w3, 2b
    ldr     w3, [x2, #0x8]                        // w3 = [0x3f104008] (random data)
    str     w3, [x0], #0x04                       // Write to buffer.
    subs    x1, x1, #0x04
    cbnz    x1, 1b
  ret


// For iproc (bcm2711, used on rpi4/rpi400 etc), see
// https://github.com/raspberrypi/linux/blob/cc333a8a1e59968156c5312c7d375b702d7d73ac/drivers/char/hw_random/iproc-rng200.c#L176-L232


// ------------------------------------------------------------------------------
// Initialise iProc RNG200 hardware random number generator (BCM2711)
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
rand_init_iproc:
  mov     x5, x30
  adrp    x1, 0xfe104000 + _start
  mov     w0, #0x00100000                         // "warmup count": the initial numbers generated are "less random" so will be discarded
                                                  // set this higher than in linux kernel, as results seem better with higher value
  str     w0, [x1, #0x10]                         // [0xfe104010] = 0x00100000
  mov     w0, #0x00000200
  str     w0, [x1, #0x24]                         // [0xfe104024] = 0x00000200
  mov     w0, #0x00007fff
  str     w0, [x1]                                // [0xfe104000] = 0x00007fff
  ret     x5


// ------------------------------------------------------------------------------
// Return 64 bits of random data in x0 from iProc RNG200
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
rand_x0_iproc:
  adrp    x1, 0xfe104000 + _start
  1:                                              // Wait until [0xfe10400c] >= 16
    ldr     w0, [x1, #0xc]
    cmp     w0, #16
    b.ls    1b
  2:
    ldrb    w0, [x1, #0x24]
    cmp     w0, #2
    b.lo    2b
  ldr     w0, [x1, #0x20]                         // w0 = [0xfe104020] (RNG_FIFO_DATA: random data)
  ldr     w2, [x1, #0x20]                         // w2 = [0xfe104020] (RNG_FIFO_DATA: random data)
  bfi     x0, x2, #32, #32                        // Copy bits from w2 into high bits of x0.
  ret


// ------------------------------------------------------------------------------
// Write random data to a buffer.
// ------------------------------------------------------------------------------
// On entry:
//   x0 = address of buffer (4 byte aligned)
//   x1 = size of buffer (multiple of 4 bytes)
// On exit:
//   x0 = first address after buffer
//   x1 = 0
//   x2 = 0xfe104000
//   x3 = last random word written to buffer
rand_block_iproc:
  and     x0, x0, #~0b11
  and     x1, x1, #~0b11
  adrp    x2, 0xfe104000 + _start
  1:                                              // Wait until [0xfe10400c] >= 16
    ldr     w3, [x2, #0xc]
    cmp     w3, #16
    b.ls    1b
  1:                                              // Loop until buffer filled
    2:                                            // Wait until [0xfe104024] (RNG_FIFO_COUNT) >= 1
      ldrb    w3, [x2, #0x24]
      cbz     w3, 2b
    ldr     w3, [x2, #0x20]                       // w3 = [0xfe104020] (RNG_FIFO_DATA: random data)
    str     w3, [x0], #0x04                       // Write to buffer.
    subs    x1, x1, #0x04
    cbnz    x1, 1b
  ret
