// Note, Raspberry Pi docs suggest that using the legacy interrupt controller on
// rpi4/rpi400 requires setting `enable_gic=0` in the config.txt file:
//   * https://www.raspberrypi.com/documentation/computers/legacy_config_txt.html#enable_gic-raspberry-pi-4-only
//
// However, this code seems to work with the legacy controller even without this
// setting in config.txt. Perhaps this is because we set `kernel_old=1`
// and thus skip the code in:
//
//   * https://github.com/raspberrypi/tools/blob/master/armstubs/armstub8.S
//
// Alternatively, maybe since the setting `enable_gic` is itself a legacy setting
// maybe the legacy interrupt controller is active by default, and this setting
// has no bearing.
//
// Or another possibility - this setting was interpreted by the Linux kernel
// rather than the GPU when bringing up the ARM and the peripheral devices.
//
// TODO: take a look at the stub to see if it is responsible for disabling the
// legacy interrupt controller. If it isn't, try to find out why we didn't
// need to explicitly enable it, or check if we are inadvertently using the
// GIC or something else without realising it.
//
// There seems to be a walkthrough of the stub code here:
//
//   * https://leiradel.github.io/2019/01/20/Raspberry-Pi-Stubs.html#armstub8s


.text


.align 2
// ------------------------------------------------------------------------------
// Load VBAR_EL1 with the exception vector table address
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
irq_vector_init:
  adr     x0, vectors                             // load VBAR_EL1 with virtual
  msr     vbar_el1, x0                            // vector table address
  ret


// ------------------------------------------------------------------------------
// Unmask IRQ interrupts via DAIF clear
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
enable_irq:
  msr     daifclr, #2
  ret


// ------------------------------------------------------------------------------
// Mask IRQ interrupts via DAIF set
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
disable_irq:
  msr     daifset, #2
  ret


// ------------------------------------------------------------------------------
// Dump all registers to UART for an invalid exception entry
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
show_invalid_entry_message:
  ret


// ------------------------------------------------------------------------------
// Enable timer IRQ on BCM2836/2837 legacy interrupt controller
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
enable_ic_bcm283x:
  adrp    x0, 0x40000000 + _start
  ldr     w1, [x0, #0x40]                         // w1 = [ARM_LOCAL register TIMER_CNTRL0] = [0x40000040]
  orr     w1, w1, 0x2                             // set bit 1 (CNT_PNS_IRQ) to cause system timer to raise an IRQ to core 0
  str     w1, [x0, #0x40]
  ret


// ------------------------------------------------------------------------------
// Initialise GIC-400 on BCM2711: enable timer and PCIe MSI interrupts
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
enable_ic_bcm2711:
                                                  // [GIC400] s3.2 p3-3 Table 3-1 -- GIC-400 register map: Distributor at base+0x1000, CPU Interface at base+0x2000
                                                  // [GIC400] s3.3 p3-4 Table 3-2 -- Distributor register summary
                                                  // [GIC400] s3.5 p3-10 Table 3-6 -- CPU interface register summary
  adrp    x1, 0xff841000 + _start                 // x1 = GICD base address
  str     wzr, [x1]                               // [0xff841000]     = [GICD_CTLR]        = 0x00000000                                             => disable GIC distributor
  mov     w3, #0x8
  mov     w4, #0xffffffff
  add     x5, x1, #0x180
  1:
    str     w4, [x5, #0x200]                      // [0xff841380+4*n] = [GICD_ICACTIVERn]  = 0xffffffff for n=0 to 7 (1 bit per interrupt)          => clear all 256 active interrupts
    str     w4, [x5, #0x100]                      // [0xff841280+4*n] = [GICD_ICPENDRn]    = 0xffffffff for n=0 to 7 (1 bit per interrupt)          => clear all 256 pending interrupts
    str     w4, [x5], #0x4                        // [0xff841180+4*n] = [GICD_ICENABLERn]  = 0xffffffff for n=0 to 7 (1 bit per interrupt)          => disable all 256 interrupts
    subs    w3, w3, #1
    b.ne    1b
  mov     w3, #0x40
  mov     w6, #0x01010101
  movz    w7, 0xa0a0a0a0 & 0xffff
  movk    w7, (0xa0a0a0a0 >> 16) & 0xffff, lsl #16
  add     x5, x1, #0x400
  2:
    str     w6, [x5, #0x400]                      // [0xff841800+4*n] = [GICD_ITARGETSRn]  = 0x01010101 for n=0 to 63 (0x3f) (8 bits per interrupt) => route all 256 interrupts to core 0
    str     w7, [x5], #0x4                        // [0xff841400+4*n] = [GICD_IPRIORITYRn] = 0xa0a0a0a0 for n=0 to 63 (0x3f) (8 bits per interrupt) => set all 256 interrupts priority to 0xa0
    subs    w3, w3, #1
    b.ne    2b
  mov     w3, #0x10
  add     x5, x1, #0xc00
  3:
    str     wzr, [x5], #0x4                       // [0xff841c00+4*n] = [GICD_ICFGRn]      = 0x00000000 for n=0 to 15 (0xf) (2 bits per interrupt) => set all 256 interrupts to level-sensitive

                                                  // Note: despite MSI usually being edge-triggered, in BCM they appear to be level sensitive:
                                                  //   https://github.com/raspberrypi/linux/blob/8ad5b3918c3e3da2999a580bbed11a72d37189be/arch/arm/boot/dts/broadcom/bcm2711.dtsi#L561
                                                  // So no need to update GICD_ICFGR11 (0xff841c2c) to e.g. 0x200 for interrupt 180 (PCIE_0_MSI).

                                                  // Note: reads of [GICD_ICFGRn] will return even bits set, e.g. 0x55555555
                                                  // [GIC400] s3.4.2 p3-6 -- GICD_ICFGRn:
                                                  //   The GIC-400 also implements the legacy encoding of the even bits in the register, designated
                                                  //   Int_config[0] in the architecture specification. The Int_config[0] bits are always read-only and
                                                  //   [are]* only provide support for legacy software. They must not be used by new software.
                                                  // *) Probably a typo
                                                  // [GICv2] s4.3.13 p4-109 -- GICD_ICFGRn:
                                                  //   On a GIC where the handling mode of peripheral interrupts is configurable, the encoding of Int_config[0] for PPIs and SPIs, is:
                                                  //     0 Corresponding interrupt is handled using the N-N model.
                                                  //     1 Corresponding interrupt is handled using the 1-N model.
                                                  // I think "1-N model" originally meant that interrupts were routed to just one core
    subs    w3, w3, #1
    b.ne    3b

  mov     w4, #0x1
  str     w4, [x1]                                // [0xff841000]     = [GICD_CTLR]        = 0x00000001                                            => forward group 1 interrupts from GIC distributor
  mov     w5, #0xf0
  str     w5, [x1, #0x1004]                       // [0xff842004]     = [GICC_PMR]         = 0x000000f0                                            => priority mask = 0xf0
  mov     w6, #0x261                              // [GICv2] s4.4.1 p4-125 Table 4-30 -- GICC_CTLR Non-secure copy (EL1)
  str     w6, [x1, #0x1000]                       // [0xff842000]     = [GICC_CTLR]        = 0x00000261                                            => EOImodeNS: 1, IRQBypDisGrp1: 1, FIQBypDisGrp1: 1, EnableGrp1: 1
  mov     w4, #0x40000000
  str     w4, [x1, #0x100]                        // [0xff841100]     = [GICD_ISENABLER0]  = 0x40000000                                            => enable interrupt 30  (0x1e) - Generic Timer (CNTP)
  mov     w4, #0x00100000
  str     w4, [x1, #0x114]                        // [0xff841114]     = [GICD_ISENABLER5]  = 0x00100000                                            => enable interrupt 180 (0xb4) - PCIE_0_MSI
  ret


// ------------------------------------------------------------------------------
// BCM2836/2837 IRQ dispatcher: route timer interrupt to handler
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
handle_irq_bcm283x:
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
  adrp    x1, 0x40000000 + _start
  ldr     w7, [x1, #0x60]                         // w7 = [0x40000060] = "Core0 IRQ Source" register
                                                  //   [BCM2836] s4.10 p7 -- Core0 IRQ Source register at offset 0x60
  cmp     w7, #0x2                                // test bit 1 (CNTPNSIRQ) [BCM2836] s4.10 p16
  b.eq    1f
  b       panic_unknown_interrupt
1:
  bl      handle_timer_irq
  ldp     x29, x30, [sp], #16                     // Pop frame pointer, procedure link register off stack.
  ret


// ------------------------------------------------------------------------------
// BCM2711 GIC IRQ dispatcher: route timer and xHCI MSI interrupts
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
handle_irq_bcm2711:
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
  adrp    x8, 0xff842000 + _start
  ldr     w7, [x8, #0xc]                          // w7 = [0xff84200c] = [GICC_IAR]   [GIC400] s3.5 p3-10 -- offset 0x000c
  str     w7, [x8, #0x10]                         // [0xff842010] = [GICC_EOIR] = [GICC_IAR]  [GIC400] s3.5 p3-10 -- offset 0x0010
                                                  // Note: Writing to GICC_EOIR before servicing interrupt, which I believe means the
                                                  // interrupt routine will be reentrant at this point. Writing to EOIR after
                                                  // handling timer may be safer.
  dsb     sy                                      // The GIC architecture specification requires that valid EOIR writes are ordered
                                                  // however probably not needed since device memory writes should already be ordered.
  cmp     w7, #0x1e
  b.eq    1f
  cmp     w7, #0xb4
  b.eq    2f
  b       panic_unknown_interrupt
1:
  bl      handle_timer_irq
  b       3f
2:
  bl      handle_xhci_irq
3:
  str     w7, [x8, #0x1000]                       // [0xff843000] = [GICC_DIR]  = [GICC_IAR]  [GIC400] s3.5 p3-10 -- offset 0x1000
                                                  // Note: Could set GICC_CTLR.EOImodeNS to 0 and not have separate GICC_EOIR and
                                                  // GICC_DIR writes, i.e. just write to GICC_EOIR after servicing interrupt.
  ldp     x29, x30, [sp], #16                     // Pop frame pointer, procedure link register off stack.
  ret


// ------------------------------------------------------------------------------
// Log unknown interrupt number and halt
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
panic_unknown_interrupt:
  b       sleep


