.text


// Sets up the generic timer for 20ms (50 Hz) interrupts.
// Period derived from cntfrq so rpi3 (19.2 MHz) and rpi4 (54 MHz) match.
// [ARMV8] sD17.11 pD17-7124 -- Generic Timer registers: CNTPCT_EL0, CNTP_CVAL_EL0, CNTP_CTL_EL0
.align 2
// ------------------------------------------------------------------------------
// Compute the 20ms timer period and arm the generic timer comparator
// ------------------------------------------------------------------------------
// On entry:
//   x28 = sysvars base
// On exit:
//   x1 corrupted
//   x2 corrupted
//   x3 corrupted
timer_init:
  ldr     w2, cntfrq                              // w2 = clock frequency (54 MHz rpi4, 19.2 MHz rpi3)
  mov     w3, #50
  udiv    w2, w2, w3                              // w2 = cntfrq / 50 = ticks per 20ms frame
  str     w2, [x28, timer_period-sysvars]
  mrs     x1, cntpct_el0                          // [ARMV8] sD17.11.20 pD17-7095 -- CNTPCT_EL0
  add     x1, x1, x2
  str     x1, [x28, next_interrupt-sysvars]
  msr     cntp_cval_el0, x1                       // [ARMV8] sD17.11.17 pD17-7085 -- CNTP_CVAL_EL0
  mov     x2, #0x1
  msr     cntp_ctl_el0, x2                        // [ARMV8] sD17.11.16 pD17-7081 -- CNTP_CTL_EL0
  ret


.align 2
// ------------------------------------------------------------------------------
// Handle timer interrupt: advance comparator by 20ms and call timed_interrupt
// ------------------------------------------------------------------------------
// On entry:
//   x28 = sysvars base
// On exit:
//   TODO
handle_timer_irq:
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
  ldr     x1, [x28, next_interrupt-sysvars]
  ldr     w2, [x28, timer_period-sysvars]         // ticks per 20ms frame (populated by timer_init)
  add     x1, x1, x2
  str     x1, [x28, next_interrupt-sysvars]
  msr     cntp_cval_el0, x1
  dsb     sy
  bl      timed_interrupt
  ldp     x29, x30, [sp], #0x10                   // Pop frame pointer, procedure link register off stack.
  ret


// ------------------------------------------------------------------------------
// 50 Hz timer tick dispatch. Currently only drives keyboard auto-repeat via
// k_repeat (roms/k_repeat.s). Future time-based work (audio sample feeder, etc.)
// would also hook in here.
// ------------------------------------------------------------------------------
// On entry:
//   x28 = sysvars base
// On exit:
//   x0-x2 corrupted (via k_repeat)
timed_interrupt:
  b       keyboard


// Set initial values to rpi4 values, and replace at runtime if different machine.
//
// RPi 4/400 (bcm2711):
//   * https://datasheets.raspberrypi.com/bcm2711/bcm2711-peripherals.pdf
//   * https://github.com/raspberrypi/firmware/issues/1374 (implies that low peripherals mode is enabled by default by VPU)


.align 3
mailbox_base:
  .quad     0xfe00b880 + _start                   // default is for rpi4
gpio_base:
  .quad     0xfe200000 + _start                   // default is for rpi4
aux_base:
  .quad     0xfe215000 + _start                   // default is for rpi4
rand_init:
  .quad     rand_init_iproc                       // default is for rpi4
rand_block:
  .quad     rand_block_iproc                      // default is for rpi4
rand_x0:
  .quad     rand_x0_iproc                         // default is for rpi4
aux_mu_baud_reg:
  .word     0x0000021d                            // default is for rpi4
cntfrq:
  .word     54000000                              // default is for rpi4
local_control:
  .quad     0x00000000ff800000                    // default is for rpi4
                                                  // note, clock is set before MMU is enabled, so store physical (not virtual) address
timer_base:
  .quad     0xfe003000 + _start                   // default is for rpi4
enable_ic:
  .quad     enable_ic_bcm2711                     // default is for rpi4
handle_irq:
  .quad     handle_irq_bcm2711                    // default is for rpi4
peripherals_start:
  .quad     0x00000000fc000000                    // default is for rpi4
                                                  // used for MMU page tables, thus physical address needed
peripherals_end:
  .quad     0x0000000100000000                    // default is for rpi4
                                                  // used for MMU page tables, thus physical address needed
pcie_init:
  .quad     pcie_init_bcm2711                     // default is for rpi4


// RPi 3B (bcm2837):
//   * https://github.com/raspberrypi/documentation/issues/325 (explains differences between bcm2835 and bcm2837)
//   * [BCM2837] -- BCM2837 peripherals are based on BCM2835
.align 3
// ------------------------------------------------------------------------------
// Peripheral address table for Raspberry Pi 3 (BCM2837)
// ------------------------------------------------------------------------------
base_rpi3:
  .quad     0x3f00b880 + _start                   // rpi3 mailbox_base
  .quad     0x3f200000 + _start                   // rpi3 gpio_base
  .quad     0x3f215000 + _start                   // rpi3 aux_base
  .quad     rand_init_bcm283x                     // rpi3 rand_init
  .quad     rand_block_bcm283x                    // rpi3 rand_block
  .quad     rand_x0_bcm283x                       // rpi3 rand_x0
  .word     0x0000010e                            // rpi3 aux_mu_baud_reg
  .word     19200000                              // rpi3 cntfrq
  .quad     0x0000000040000000                    // rpi3 local_control (physical address, not virtual)
  .quad     0x3f003000 + _start                   // rpi3 timer_base
  .quad     enable_ic_bcm283x                     // rpi3 enable_ic
  .quad     handle_irq_bcm283x                    // rpi3 handle_irq
  .quad     0x000000003f000000                    // rpi3 peripherals_start (physical address, not virtual)
  .quad     0x0000000040200000                    // rpi3 peripherals_end (physical address, not virtual)
  .quad     0x0000000000000000                    // rpi3 pcie_init (0 => no pcie)


.align 2
// ------------------------------------------------------------------------------
// Detect RPi model from MIDR_EL1 and load peripheral base addresses
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
set_peripherals_addresses:
  mrs     x0, midr_el1                            // [ARMV8] sD17.2.100 pD17-6115 -- MIDR_EL1, Main ID Register
                                                  // x0 = Main ID Register value 0xNNNNNNNNIIVAPPPR, where:
                                                  //
                                                  // NNNNNNNN = N/A (reserved)
                                                  // II = Implementer
                                                  //   0x00: Reserved for software use
                                                  //   0xc0: Ampere Computing
                                                  //   0x41: Arm Limited
                                                  //   0x42: Broadcom Corporation
                                                  //   0x43: Cavium Inc.
                                                  //   0x44: Digital Equipment Corporation
                                                  //   0x46: Fujitsu Ltd.
                                                  //   0x49: Infineon Technologies AG
                                                  //   0x4d: Motorola or Freescale Semiconductor Inc.
                                                  //   0x4e: NVIDIA Corporation
                                                  //   0x50: Applied Micro Circuits Corporation
                                                  //   0x51: Qualcomm Inc.
                                                  //   0x56: Marvell International Ltd.
                                                  //   0x69: Intel Corporation
                                                  //   0xc0: Ampere Computing
                                                  // V = Variant
                                                  // A = Architecture
                                                  //   0x1: Armv4
                                                  //   0x2: Armv4T
                                                  //   0x3: Armv5(obsolete)
                                                  //   0x4: Armv5T
                                                  //   0x5: Armv5TE
                                                  //   0x6: Armv5TEJ
                                                  //   0x7: Armv6
                                                  //   0xf: Architectural features are individually identified in the ID_* registers, see 'ID registers'
                                                  // PPP = Part Number
                                                  //   0xd03: Raspberry Pi 3B (potentially also 3A+, 3B+, CM 3+, ...)
                                                  // R = Revision
                                                  //
                                                  // e.g.
                                                  //   0x00000000410fd034 (value on my Raspberry Pi 3 Model B)
                                                  //   => Implementer = 0x41 = Arm Limited
                                                  //   => Variant = 0x0 (r0 for r0p4)
                                                  //   => Architecture = 0xf = "features are identified in the ID_* registers"
                                                  //   => Part Number = 0xd03 (presumably, Raspberry Pi 3)
                                                  //   => Revision = 0x4 (p4 for r0p4)
                                                  //   0x00000000410fd083 (value on my Raspberry Pi 400)
                                                  //   => Implementer = 0x41 = Arm Limited
                                                  //   => Variant = 0x0 (r0 for r0p3)
                                                  //   => Architecture = 0xf = "features are identified in the ID_* registers"
                                                  //   => Part Number = 0xd08 (presumably, Raspberry Pi 4)
                                                  //   => Revision = 0x3 (p3 for r0p3)


// mrs     x1, revidr_el1                          // e.g. x1 = 0x80 (value on my Raspberry Pi 3 Model B)
                                                  //           0x00 (value on my Raspberry Pi 400)
  and     x0, x0, #0xfff0
  mov     x1, #0xd030
  cmp     x0, x1
  b.ne    1f
  adr     x0, base_rpi3
  adr     x1, mailbox_base
  ldp     x2, x3, [x0]                            //  x2 = [rpi3 mailbox_base]
                                                  //  x3 = [rpi3 gpio_base]
  ldp     x4, x5, [x0, #16]                       //  x4 = [rpi3 aux_base]
                                                  //  x5 = [rpi3 rand_init]
  ldp     x6, x7, [x0, #32]                       //  x6 = [rpi3 rand_block]
                                                  //  x7 = [rpi3 rand_x0]
  ldp     x8, x9, [x0, #48]                       //  x8 = [rpi3 aux_mu_baud_reg] (bits 0-31)
                                                  //       [rpi3 cntfrq] (bits 32-63)
                                                  //  x9 = [rpi3 local_control]
  ldp     x10, x11, [x0, #64]                     // x10 = [rpi3 timer_base]
                                                  // x11 = [rpi3 enable_ic]
  ldp     x12, x13, [x0, #80]                     // x12 = [rpi3 handle_irq]
                                                  // x13 = [rpi3 peripherals_start]
  ldp     x14, x15, [x0, #96]                     // x14 = [rpi3 peripherals_end]
                                                  // x15 = [rpi3 pcie_init]
  stp     x2, x3, [x1]                            // [mailbox_base]      = [rpi3 mailbox_base]
                                                  // [gpio_base]         = [rpi3 gpio_base]
  stp     x4, x5, [x1, #16]                       // [aux_base]          = [rpi3 aux_base]
                                                  // [rand_init]         = [rpi3 rand_init]
  stp     x6, x7, [x1, #32]                       // [rand_block]        = [rpi3 rand_block]
                                                  // [rand_x0]           = [rpi3 rand_x0]
  stp     x8, x9, [x1, #48]                       // [aux_mu_baud_reg]   = [rpi3 aux_mu_baud_reg] (32 bit)
                                                  // [cntfrq]            = [rpi3 cntfrq] (32 bit)
                                                  // [local_control]     = [rpi3 local_control]
  stp     x10, x11, [x1, #64]                     // [timer_base]        = [rpi3 timer_base]
                                                  // [enable_ic]         = [rpi3 enable_ic]
  stp     x12, x13, [x1, #80]                     // [handle_irq]        = [rpi3 handle_irq]
                                                  // [peripherals_start] = [rpi3 peripherals_start]
  stp     x14, x15, [x1, #96]                     // [peripherals_end]   = [rpi3 peripherals_end]
                                                  // [pcie_init]         = [rpi3 pcie_init]
1:
  ret


.align 2
// ------------------------------------------------------------------------------
// Emulates https://github.com/raspberrypi/tools/blob/2e59fc67d465510179155973d2b959e50a440e47/armstubs/armstub8.S#L98-L102
// which seems to be important for the frequency at which ARM register cntpct_el0 increments (used by wait_usec)
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
set_clocks:
  ldr     x0, local_control
                                                  // +=======================+
                                                  // | BCM ARM LOCAL CONTROL |
                                                  // +=======================+
                                                  //
                                                  // rpi3: [BCM2836] s4.2 p9 -- ARM Local Control register
                                                  // rpi4: [BCM2711] s6.5 p93 -- ARM Local Control register
                                                  //
                                                  // TIMER_INCREMENT [8] = 0b0 => main timer increments by 1 (not 2)
                                                  // PROC_CLK_TIMER  [7] = 0b0 => main timer driven by fixed frequency crystal clock reference
                                                  // AXIERRIRQ_EN    [6] = 0b0 => main timer driven by fixed frequency crystal clock reference
  str     wzr, [x0]
  mov     w1, #0x80000000
  str     w1, [x0, 8]
  ret


// ------------------------------------------------------------------------------
// Zero a block of memory in 8-byte increments
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
memzero:
1:
  str     xzr, [x0], #8
  subs    x1, x1, #0x8
  b.gt    1b
  ret


