// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text
.align 2


// ------------------------------------------------------------------------------
// Main Key Waiting Loop
// Waits for a key press, then dispatches it.
//
// The loop:
//   1. Reset L-mode (mode_l_2)
//   2. Poll FLAGS bit 5 (new key available), sleeping via WFI between polls
//   3. Read LASTK, clear FLAGS bit 5
//   4. Dispatch key via process_key (L2669)
//   5. Repeat
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
wait_key_press:                          // L2653

  bl      mode_l_2                                // Reset 'L' mode.

  // Poll FLAGS bit 5 with WFI between polls.
  // WFI sleeps the CPU until the next interrupt (xHCI MSI for keyboard,
  // or timer). On wake, we check if a new key is available.
1:
  dsb     sy                                      // complete prior MMIO accesses before sleeping
  wfi                                             // Sleep until interrupt
  ldrb    w0, [x28, FLAGS-sysvars]
  tbz     w0, #5, 1b                              // Loop if FLAGS bit 5 not set

  // New key available: read LASTK and clear FLAGS bit 5
  and     w0, w0, #~0x20                          // Clear bit 5
  strb    w0, [x28, FLAGS-sysvars]
  ldrb    w0, [x28, LASTK-sysvars]                // w0 = key code

  // Dispatch key press (skip key click for now, no sound hardware)
  bl      process_key                             // L2669: process the key press

  b       wait_key_press                          // Loop
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text
.align 2


// ------------------------------------------------------------------------------
// Process Key Press
// Handle key presses for menus and the Editor.
// Uses compact table-driven dispatch: handler = table + offset * 4, where each
// offset is a signed halfword. Saves 6 bytes per entry vs 8-byte addresses, and
// the search loop is reusable across menu keys (L2577) and editing keys (L2537).
// Equivalent to rom0.s L2669 + L3FCE.
// ------------------------------------------------------------------------------
// On entry:
//   w0 = key code
//   x28 = sysvars base
// On exit:
//   register values depend on key hander routines called
process_key:                             // L2669
  stp     x29, x30, [sp, #-16]!
  mov     x29, sp

  // Check if menu is displayed
  ldrb    w1, [x28, EC0D-sysvars]
  tbz     w1, #1, 3f                              // bit 1 clear = no menu, editor path (not yet implemented)

  // Menu is displayed, search menu keys table
  adr     x1, menu_keys_table

  // Search key action table at x1 and call matched handler.
  // Table format: .hword count, off0..offN-1; .byte key0..keyN-1
  // Each offset is (handler - table) / 4, as a signed halfword.
  ldrh    w2, [x1]                                // w2 = number of entries
  add     x3, x1, #2                              // x3 = offsets array (halfword entries)
  add     x4, x3, x2, lsl #1                      // x4 = codes array (past offsets)
  mov     w5, #0                                  // w5 = index
  1:
    cbz     w2, 3f                                // no more entries, no match
    ldrb    w6, [x4, x5]                          // w6 = key code from table
    cmp     w0, w6
    b.eq    2f                                    // match found
    add     w5, w5, #1
    sub     w2, w2, #1
    b       1b
2:
  // Match found: handler = table + offset * 4
  ldrsh   x6, [x3, x5, lsl #1]                    // x6 = signed halfword offset
  add     x6, x1, x6, lsl #2                      // x6 = handler address
  blr     x6
3:
  ldp     x29, x30, [sp], #0x10
  ret
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text
.align 2


// ------------------------------------------------------------------------------
// Menu Select Handler
// Execute the menu item at the current index.
// ------------------------------------------------------------------------------
// On entry:
//   x28 = sysvars base
// On exit:
//   jumps to selected handler (does not return to caller)
menu_select:                             // L2717
  ldrb    w0, [x28, EC0C-sysvars]                 // w0 = current menu index
  adr     x2, main_menu_jump_table
  add     w0, w0, #1                              // skip count entry (first quad)
  ldr     x3, [x2, x0, lsl #3]                    // x3 = handler address
  br      x3                                      // jump to handler (does not return)
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text
.align 2


// ------------------------------------------------------------------------------
// Menu Up Handler
// Move menu highlight up one item.
// Equivalent to rom0.s L272E.
// ------------------------------------------------------------------------------
// On entry:
//   x28 = sysvars base
// On exit:
//   returns to caller
menu_up:                                 // L272E
  stp     x29, x30, [sp, #-16]!
  mov     x29, sp
  ldrb    w1, [x28, EC0C-sysvars]                 // w1 = current menu index
  bl      toggle_menu_highlight                   // unhighlight current item
  ldrb    w1, [x28, EC0C-sysvars]                 // re-read index
  subs    w1, w1, #1                              // w1 = new index; set flags
  b.pl    1f                                      // if >= 0, use new index
  adr     x2, main_menu_jump_table                // wrap to bottom
  ldr     x3, [x2]                                // x3 = number of menu entries
  sub     w1, w3, #1                              // w1 = last item index (entries - 1)
1:
  strb    w1, [x28, EC0C-sysvars]                 // store new index
  bl      toggle_menu_highlight                   // highlight new item
  ldp     x29, x30, [sp], #0x10
  ret
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text
.align 2


// ------------------------------------------------------------------------------
// Menu Down Handler
// Move menu highlight down one item.
// Equivalent to rom0.s L2731.
// ------------------------------------------------------------------------------
// On entry:
//   x28 = sysvars base
// On exit:
//   returns to caller
menu_down:                               // L2731
  stp     x29, x30, [sp, #-16]!
  mov     x29, sp
  ldrb    w1, [x28, EC0C-sysvars]                 // w1 = current menu index
  bl      toggle_menu_highlight                   // unhighlight current item
  ldrb    w1, [x28, EC0C-sysvars]                 // re-read index
  add     w1, w1, #1                              // w1 = new index
  adr     x2, main_menu_jump_table
  ldr     x3, [x2]                                // x3 = number of menu entries
  sub     w3, w3, #1                              // w3 = max index (entries - 1)
  cmp     w1, w3
  b.le    1f                                      // if <= max index, use new index
  mov     w1, #0                                  // wrap to top
1:
  strb    w1, [x28, EC0C-sysvars]                 // store new index
  bl      toggle_menu_highlight                   // highlight new item
  ldp     x29, x30, [sp], #0x10
  ret
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


