.text


.align 2
// ------------------------------------------------------------------------------
// Plot a straight line of pixels using delta stepping
// ------------------------------------------------------------------------------
// On entry:
//   w19 = start y
//   w20 = start x
//   w21 = y delta for next pixel
//   w22 = x delta for next pixel
//   w23 = number of pixels
// On exit:
//   TODO
plot_line:                               // L3719
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
  1:
    mov     w12, w19
    mov     w13, w20
    bl      plot_sub_1
    add     w19, w19, w21
    add     w20, w20, w22
    subs    w23, w23, #1
    b.ne    1b
  ldp     x29, x30, [sp], #0x10                   // Pop frame pointer, procedure link register off stack.
  ret
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text


.align 2
// ------------------------------------------------------------------------------
// Print an AT control sequence to position the cursor at (w8, w9)
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
print_at:                                // L372B
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
  mov     w0, #0x16
  bl      print_w0
  mov     w0, w8
  bl      print_w0
  mov     w0, w9
  bl      print_w0
  ldp     x29, x30, [sp], #0x10                   // Pop frame pointer, procedure link register off stack.
  ret
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text
.align 2


// ------------------------------------------------------------------------------
// Print a 0xff-terminated string byte by byte via print_w0
// ------------------------------------------------------------------------------
// On entry:
//   x4 = address of string in memory
// On exit:
//   x0
//   ....
print_str_ff:                            // L3733
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
1:
  ldrb    w0, [x4], #1
  cmp     w0, #0xff
  b.eq    2f                                      // char 0xff => end of string, so exit loop
  stp     x7, x4, [sp, #-16]!
  bl      print_w0
  ldp     x7, x4, [sp], #0x10
  b       1b
2:
  ldp     x29, x30, [sp], #0x10                   // Pop frame pointer, procedure link register off stack.
  ret
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


