.text
.align 2


// -------------------------------------------------------------------------
//
//         {fl}{br}{   paper   }{  ink    }    The temporary colour attributes
//          ___ ___ ___ ___ ___ ___ ___ ___    system variable.
// ATTR_T  |   |   |   |   |   |   |   |   |
//         |   |   |   |   |   |   |   |   |
//         |___|___|___|___|___|___|___|___|
//           7   6   5   4   3   2   1   0
//
//
//         {fl}{br}{   paper   }{  ink    }    The temporary mask used for
//          ___ ___ ___ ___ ___ ___ ___ ___    transparent colours. Any bit
// MASK_T  |   |   |   |   |   |   |   |   |   that is 1 shows that the
//         |   |   |   |   |   |   |   |   |   corresponding attribute is
//         |___|___|___|___|___|___|___|___|   taken not from ATTR-T but from
//           7   6   5   4   3   2   1   0     what is already on the screen.
//
//
//         {paper9 }{ ink9 }{ inv1 }{ over1}   The print flags. Even bits are
//          ___ ___ ___ ___ ___ ___ ___ ___    temporary flags. The odd bits
// P_FLAG  |   |   |   |   |   |   |   |   |   are the permanent flags.
//         | p | t | p | t | p | t | p | t |
//         |___|___|___|___|___|___|___|___|
//           7   6   5   4   3   2   1   0
//
// -----------------------------------------------------------------------


// ------------------------------------------------------------------------------
//  The colour system variable handler.
// This is an exit branch from PO-1-OPER, PO-2-OPER
// w5 holds control character 0x10 (INK) to 0x15 (OVER)
// w0 holds legal/illegal parameter. Legal values are:
//   0-9 for ink/paper
//   0,1 or 8 for bright/flash,
//   0 or 1 for over/inverse.
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
co_temp_5:                               // L2211
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
  cmp     w5, #0x11
  b.ls    4f                                      // handle 0x10 (INK) and 0x11 (PAPER)
  cmp     w5, #0x13
  b.ls    10f                                     // handle 0x12 (FLASH) and 0x13 (BRIGHT)
// Handle INVERSE (0x14) and OVER (0x15)
  cmp     w0, #0x01
  b.ls    1f
  bl      report_k
// INVERSE 0/1 or OVER 0/1
1:
  stp     x4, x5, [sp, #-16]!
  ldrb    w4, [x28, P_FLAG-sysvars]               // w4 = current P_FLAG
  tbnz    w5, #0, 2f                              // jump ahead if OVER
// INVERSE 0/1
  bfi     w4, w0, #2, #1
  b       3f
// OVER 0/1
2:
  bfi     w4, w0, #0, #1
3:
  strb    w4, [x28, P_FLAG-sysvars]
  ldp     x4, x5, [sp], #16
  b       12f
// Handle INK (0x10) and PAPER (0x11)
// Zero flag clear for INK, set for PAPER
4:                                       // L2234
  stp     x0, x1, [sp, #-16]!
  stp     x2, x3, [sp, #-16]!
  stp     x4, x5, [sp, #-16]!
  stp     x6, x7, [sp, #-16]!
  mov     w1, #0x38
  mov     w2, #0x07
  lsl     w3, w0, #3                              // w3 holds colour in paper bits (3-5)
  csel    w1, w1, w2, eq                          // w1 = 0x07 (INK) or 0x38 (PAPER)
  csel    w3, w3, w0, eq                          // w3 = colour in bits 0-2 if INK, bits 3-5 if PAPER
  cmp     w0, #0x09
  b.ls    5f
  bl      report_k
  b       12f
5:                                       // L2246
// PAPER 0-9 / INK 0-9
  ldrb    w6, [x28, MASK_T-sysvars]               // w6 = current MASK_T
  ldrb    w4, [x28, P_FLAG-sysvars]               // w4 = current P_FLAG
  add     w7, w1, #0x09                           // w7 = 0x10 (INK) or 0x41 (PAPER)
  bic     w7, w7, #1                              // w7 = 0x10 (INK) or 0x40 (PAPER)
  cmp     w0, #0x08                               // INK 8 / PAPER 8 ?
  b.eq    6f
  ldrb    w2, [x28, ATTR_T-sysvars]
  bic     w2, w2, w1                              // clear bits in ATTR_T for ink or paper
  b.hi    7f                                      // jump ahead if INK 9 / PAPER 9
// INK 0-7 / PAPER 0-7
  orr     w2, w2, w3                              // colour in w2 bits 0-2 (ink) or 3-5 (paper)
  bic     w6, w6, w1                              // clear bits in MASK_T for ink or paper
  bic     w4, w4, w7                              // clear P_FLAG bit 4/6 for INK or PAPER 9
  b       8f
// INK 8 / PAPER 8
6:
  orr     w6, w6, w1                              // set bits in MASK_T for ink or paper
  bic     w4, w4, w7                              // clear P_FLAG bit 4/6 for INK or PAPER 9
  b       9f
// INK 9 / PAPER 9
7:
  orr     w6, w6, w1                              // set bits in MASK_T for ink or paper
  orr     w4, w4, w7                              // set P_FLAG bit 4/6 for INK or PAPER 9
  mvn     w3, w1                                  // w3 = bitwise NOT of w1 (0xfffffff8 for INK 9 or 0xffffffc7 for PAPER 9)
  mov     w5, #0x24
  and     w3, w3, w5                              // 0x20 for INK 9 or 0x04 for PAPER 9
  and     w3, w3, w2                              // Leading PAPER bit of ATTR_T in bit 5 if INK 9 or leading INK bit of ATTR_T in bit 2 if PAPER 9
  cmp     w3, wzr
  csel    w3, w1, wzr, eq                         // if leading INK/PAPER bit
  orr     w2, w2, w3
8:
  strb    w2, [x28, ATTR_T-sysvars]
9:
  strb    w6, [x28, MASK_T-sysvars]
  strb    w4, [x28, P_FLAG-sysvars]
  ldp     x6, x7, [sp], #16
  ldp     x4, x5, [sp], #16
  ldp     x2, x3, [sp], #16
  ldp     x0, x1, [sp], #16
  b       12f
// Handle FLASH (0x12) and BRIGHT (0x13)
// Zero flag clear for FLASH, set for BRIGHT
10:                                      // L2273
  mov     w1, #0x40
  mov     x2, #0x80
  csel    w1, w1, w2, eq                          // w1 = 128 (FLASH) or 64 (BRIGHT)
  ldrb    w2, [x28, ATTR_T-sysvars]
  ldrb    w3, [x28, MASK_T-sysvars]
  cmp     w0, #0x01
  b.lo    13f
  b.eq    14f
  cmp     w0, #0x08
  b.eq    15f
  bl      report_k
  b       12f
11:
  strb    w2, [x28, ATTR_T-sysvars]
  strb    w3, [x28, MASK_T-sysvars]
12:
  ldp     x29, x30, [sp], #16                     // Pop frame pointer, procedure link register off stack.
  ret
// BRIGHT 0 / FLASH 0
13:
  bic     w2, w2, w1
  bic     w3, w3, w1
  b       11b
// BRIGHT 1 / FLASH 1
14:
  orr     w2, w2, w1
  bic     w3, w3, w1
  b       11b
// BRIGHT 8 / FLASH 8
15:
  bic     w2, w2, w1                              // not needed, but consistent with 128K
  orr     w3, w3, w1
  b       11b


// ------------------------------------------------------------------------------
// Report error K - Invalid colour (stub)
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
report_k:                                // L2244
  ret
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text


.align 2
// ------------------------------------------------------------------------------
// Calculate display file address and bit offset for a pixel coordinate
// ------------------------------------------------------------------------------
// On entry:
//   x12 = y (0 to 927)
//   x13 = x (0 to 1727)
// On exit:
//   x11 = display_file + 216*(20*(16*((927-y)/320)+(((927-y)%320)&0x0f))+((927-y)%320>>4))+x/8
//   x12 = display_file
//   x14 = x%8
pixel_addr:                              // L22AA
  mov     x11, 927
  sub     x12, x11, x12                           // x12 = 927-y
  mov     x11, #0xcccd000000000000                // x11 = 14757451553962983424
  umulh   x14, x11, x12                           // x14 = 14757451553962983424 * (927-y) / 2^64 = (4/5) * (927-y)
  lsr     x14, x14, #8                            // x14 = int((927-y)/320)
  add     x11, x14, x14, lsl #2                   // x11 = 5 * int((927-y)/320)
  sub     x11, x12, x11, lsl #6                   // x11 = (927-y) - 320 * int((927-y)/320) = (927-y)%320
  lsl     x14, x14, #4                            // x14 = 16*((927-y)/320)
  bfxil   x14, x11, #0, #4                        // x14 = 16*((927-y)/320) + (((927-y)%320)&0x0f) = 16*((927-y)/320) + ((927-y)&0x0f)
  add     x14, x14, x14, lsl #2                   // x14 = 5*(16*((927-y)/320) + ((927-y)&0x0f))
  lsl     x14, x14, #2                            // x14 = 20*(16*((927-y)/320)+((927-y)&0x0f))
  add     x14, x14, x11, lsr #4                   // x14 = 20*(16*((927-y)/320)+((927-y)&0x0f))+((927-y)%320>>4)
  add     x11, x14, x14, lsl #3                   // x11 = 9*(20*(16*((927-y)/320)+((927-y)&0x0f))+((927-y)%320>>4))
  lsl     x11, x11, #3                            // x11 = 72*(20*(16*((927-y)/320)+((927-y)&0x0f))+((927-y)%320>>4))
  add     x11, x11, x11, lsl #1                   // x11 = 216*(20*(16*((927-y)/320)+((927-y)&0x0f))+((927-y)%320>>4))
  adr     x12, display_file                       // x12 = display_file
  add     x11, x11, x12                           // x11 = display_file + 216*(20*(16*((927-y)/320)+((927-y)&0x0f))+((927-y)%320>>4))
  add     x11, x11, x13, lsr #3                   // x11 = display_file + 216*(20*(16*((927-y)/320)+((927-y)&0x0f))+((927-y)%320>>4))+x/8)
  and     x14, x13, #0x07                         // x14 = x13%8
  ret
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text


.align 2
// ------------------------------------------------------------------------------
// Plot a single pixel with OVER/INVERSE handling and attribute update
//
// A screen byte holds 8 pixels so it is necessary to rotate a mask
// into the correct position to leave the other 7 pixels unaffected.
// However all 256 pixels in the character cell take any embedded colour
// items.
// A pixel can be reset (inverse 1), toggled (over 1), or set (with inverse
// and over switches off). With both switches on, the byte is simply put
// back on the screen though the colours may change.
// ------------------------------------------------------------------------------
// On entry:
//   x12 = y (0 to 927)
//   x13 = x (0 to 1727)
// On exit:
//   TODO
plot_sub_1:                              // L22E9
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
  bl      pixel_addr                              // x11 = display file address, x14 = x & 0x07
  mov     x0, x11                                 // x0 = display file address (needed in x0 for po_attr)
  mov     w12, 0x80                               // w12 = mask for leftmost pixel of display file byte
  lsr     w12, w12, w14                           // w12 = mask for pixel bit (7-w14)
  ldrb    w13, [x28, P_FLAG-sysvars]              // w13 = [P_FLAG]
  ldrb    w14, [x0]                               // w14 = current display file value
  tbnz    w13, #0, 1f
// OVER 0
  tbnz    w13, #2, 2f
// OVER 0, INVERSE 0
  orr     w14, w14, w12
  b       3f
// OVER 1
1:
  tbnz    w13, #2, 4f
// OVER 1, INVERSE 0
  eor     w14, w14, w12
  b       3f
// OVER 0, INVERSE 1
2:
  bic     w14, w14, w12
3:
  strb    w14, [x0]
4:
  bl      po_attr
  ldp     x29, x30, [sp], #0x10                   // Pop frame pointer, procedure link register off stack.
  ret
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text
.align 2
// ------------------------------------------------------------------------------
// Print keywords (with possible leading and/or trailing space) or UDGs (chars 0x90-0xff).
// ------------------------------------------------------------------------------
// On entry:
//   w3 = char (144-255 / 0x90-0xff)
//   x28 = sysvars
//   If printing a keyword:
//     [[CURCHL]] = print routine to call
//     ... any settings that routine at [[CURCHL]] requires ...
//   Else: (printing a UDG):
//     w1 = (109 - column), or 1 for end-of-line
//     x2 = address in display file / printer buffer(?)
//     [P_FLAG] bit 0 and bit 2 (temp OVER, temp INVERSE)
//     [UDG] = address of UDG character table (address of UDG 'A' bitmap)
//     If printer not in use:
//       [P_FLAG] bit 4 and bit 6 (temp INK 9, temp PAPER 9)
//       [TV_FLAGS] bit 0 (lower screen in use or not)
//       [DF_SZ]
//       [ATTR_T]
//       [MASK_T]
//       Display file / attribute file data at character cell
//   If w3 = 0xa3 / 0xa4:
//     [FLAGS] bit 4 set to 0 for UDG T/U or 1 for PLAY / SPECTRUM keyword
//     If [FLAGS] bit 4 set:
//       [FLAGS] bit 0 clear if leading space required before PLAY / SPECTRUM keyword
//   If printer in use:
//     Bit 1 of FLAGS set
//     [P_POSN_X]
//     [PR_CC]
//   If upper screen in use:
//     w0 = 60 - line offset into section (60 = top line of S/K, 59 = second line, etc)
//     Bit 1 of FLAGS clear
//     Bit 0 of [TV_FLAG] clear
//     [S_POSN_{X,Y}]
//     [DF_CC]
//   If lower screen in use:
//     w0 = 60 - line offset into section (60 = top line of S/K, 59 = second line, etc)
//     Bit 1 of FLAGS clear
//     Bit 0 of [TV_FLAG] set
//     [S_POSN_{X,Y}_L]
//     [DF_CC_L]
// On exit:
//   If printing a UDG:
//     [FLAGS] bit 0 cleared
//     If printer in use:
//       printer buffer updated (and potentially flushed)
//       <other unknown stuff>
//     Else:
//       display file and attributes file updated
//       x0 = 60 - new line offset into section
//       x1 = 109 - new column, or 1 for end-of-line
//       x2 += 2 (correct new cursor memory location, unless at first char of screen third)
//       Plus po_attr register changes (excluding x24):
//         x3
//         x5
//         x6
//         x7
//         x8
//         x9 = fb_req
//         x10
//         x11
//         x12
//         x13
//         x14
//         x15
//         x16
//         x17
//         x18
//         NZCV
//       If was at end-of-line before printing (entry x1 == 1):
//         cl_set register updates:
//           x4 = y offset into screen third of updated position (not entry position)
//         If lower screen:
//           [S_POSN_X_L] = 109 (start of line)
//           [S_POSN_Y_L] = x0-1 (line below)
//           [ECHO_E_X] = 109 (start of line)
//           [ECHO_E_Y] = x0-1 (line below)
//           [DF_CC_L] set to display file address for [S_POSN_{X,Y}_L]
//         If upper screen:
//           [S_POSN_X] = 109 (start of line)
//           [S_POSN_Y] = x0-1 (line below)
//           [DF_CC] set to display file address for [S_POSN_{X,Y}]
//       Else:
//         x4 = address of 32 byte character bit pattern
//   If printing keyword:
//     If printer in use:
//       for SPECTRUM/PLAY:
//         x0 = ' ', or whatever [[CURCHL]] changes it to
//         x1 = [[CURCHL]], or whatever [[CURCHL]] changes it to
//         x2 unchanged
//       for other keywords:
//         w0 = [FLAGS]
//         w1 = [P_POSN_X] (109 - actual printer column)
//         x2 = [PR_CC] (address in printer buffer)
//     If upper screen in use:
//       w0 = [S_POSN_Y] (60 - actual upper screen row)
//       w1 = [S_POSN_X] (109 - actual upper screen column)
//       x2 = [DF_CC] (address of upper screen cursor in display file)
//     If lower screen in use:
//       w0 = [S_POSN_Y_L] (120 - [DF_SZ] - actual lower screen row)
//       w1 = [S_POSN_X_L] (109 - actual lower screen column)
//       x2 = [DF_CC_L] (address of lower screen cursor in display file)
//     for SPECTRUM/PLAY:
//       x3 = 0 (SPECTRUM) / 1 (PLAY)
//       x4 = [FLAGS]
//       x5 = 4
//     for other keywords:
//       x3 -= 0xa5 (165)
//       x4 = first address after zero termination byte of BASIC keyword in token table
//       x5 = exit x3
//     x6 = last char of keyword (not including the trailing zero byte nor any added trailing space)
//     for RND/INKEY$/PI/<=/>=/<>/OPEN #/CLOSE #:
//       nzcv = 0b1000
//     for FN:
//       nzcv = 0b0110, or whatever [[CURCHL]] changes it to
//     for everything else:
//       nzcv = 0b0010, or whatever [[CURCHL]] changes it to
//     x7, x8, x9, x10, x11, x12, x13, x14, x15, x16, x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27 =
//       whataver [[CURCHL]] does with them
print_token_udg_patch:                   // L3B9F
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
  cmp     w3, #0xa3                               // Is char 'SPECTRUM' (128K mode) / UDG T (48K mode)?
  b.eq    2f                                      // If so, jump forward to 2:.
  cmp     w3, #0xa4                               // Is char 'PLAY' (128K mode) / UDG U (48K mode)?
  b.eq    2f                                      // If so, jump forward to 2:.
1:
  subs    w3, w3, #0xa5                           // w3 = (char - 165)
  b.pl    3f                                      // If char is token (w3 >= 0) jump forward to 3:.
  // UDG character
  bl      rejoin_po_t_udg                         // Rejoin 48K BASIC routine.
  b       5f                                      // Exit routine.
2:
  // SPECTRUM/PLAY token (128K mode) or T/U UDG (48K mode)

  // TODO: See if we can find an alternative unused register for storing FLAGS
  // in, since we read it multiple times below.

  ldrb    w4, [x28, FLAGS-sysvars]                // w4 = [FLAGS]
  tbz     w4, #4, 1b                              // If in 48K mode, jump back to 1:.
  // SPECTRUM or PLAY token in 128K mode
  adr     x4, tkn_spectrum                        // x4 = address of "SPECTRUM" string
  adr     x5, tkn_play                            // x5 = address of "PLAY" string
  subs    w3, w3, #0xa3                           // w3 = 0 for "SPECTRUM" or 1 for "PLAY"
  csel    x4, x4, x5, eq                          // x4 = correct address for token string
  mov     w5, #0x04                               // Indicate trailing space required
  bl      po_table_1                              // Print SPECTRUM or PLAY.
  // TODO: set carry flag??? Why???
  ldrb    w4, [x28, FLAGS-sysvars]                // w4 = [FLAGS]
  tbnz    w4, #1, 5f                              // If printer in use, jump forward to 5:.
  // Printer not in use
  b       4f
3:
  bl      po_tokens
4:
  bl      po_fetch
5:
  ldp     x29, x30, [sp], #0x10                   // Pop frame pointer, procedure link register off stack.
  ret
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text
.align 0
tkn_spectrum:                            // L3BD2
  .asciz "SPECTRUM"


tkn_play:                                // L3BDA
  .asciz "PLAY"
// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.text
.align 2


// ------------------------------------------------------------------------------
// This routine generates a display showing all possible colours and emitting a
// continuous cycle of a 440 Hz tone for 1 second followed by silence for 1
// second. Its purpose on the Spectrum 128K was to ease the tuning in of TV sets
// to the Spectrum 128's RF signal. For the Spectrum +4 it is mostly there for
// the sake of nostalgia. The display consists of vertical stripes of width 12
// character squares showing each of the eight colours available at both their
// normal (six chargs) and bright (six chars) intensities. The display begins
// with white (colour 7) on the left progressing down to black on the right
// (colour 0). Within each colour stripe in the first eight rows the year '2022'
// is shown in varying ink colours. This leads to a display that shows all
// possible ink colours on all possible paper colours.
// ------------------------------------------------------------------------------
// On entry:
//   TODO
// On exit:
//   TODO
tv_tuner:                                // L3C10
  stp     x29, x30, [sp, #-16]!                   // Push frame pointer, procedure link register on stack.
  mov     x29, sp                                 // Update frame pointer to new stack location.
// TODO: test for shift-space combo; if _not_ both pressed, return from routine
  movz    w0, BORDER_COLOUR & 0xffff
  movk    w0, (BORDER_COLOUR >> 16) & 0xffff, lsl #16
  bl      paint_border                            // Paint border
  mov     w0, #2
  bl      chan_open                               // Main screen in use
  strb    wzr, [x28, TV_FLAG-sysvars]             // [TV_FLAG] = 0
  mov     w7, #0x3f                               // initial attribute value
1:
  and     w0, w7, #0x07
  add     w0, w0, #0x35
  mov     w1, #0x67
  bl      cl_set
2:
  strb    w7, [x28, ATTR_T-sysvars]               // update temp attribute sysvar
  adr     x4, tvt_data
  bl      print_str_ff
  subs    w7, w7, #8
  b.hs    2b
  add     w7, w7, #0x3f
  cmp     w7, #0x37
  b.eq    5f
  b       1b
5:
  adr     x19, attributes_file
  add     x20, x19, 108*8
  adr     x21, attributes_file_end
6:
  mov     x0, x20
  ldrb    w1, [x19], #0x01
  add     x20, x20, #0x01
  bl      poke_address
  cmp     x20, x21
  b.ne    6b
7:
// b       7b
  ldp     x29, x30, [sp], #0x10                   // Pop frame pointer, procedure link register off stack.
  ret


tvt_data:                                // L3C8F
  .byte   0x13, 0x00                              // Bright, off
  .ascii  " 2022 "
  .byte   0x13, 0x01                              // Bright, on
  .ascii  " 2022 "
  .byte   0xff                                    // Can't use 0x00 for termination byte since in string
tvt_data_end:


// This file is part of the Spectrum +4 Project.
// Licencing information can be found in the LICENCE file
// (C) 2021-2026 Spectrum +4 Authors. All rights reserved.


.section bss_roms, "aw", %nobits


.align 12                                         // Ensure sysvars at 4KB boundary
sysvars:
.align 0
COL:
  .space 1                                        // L5B63: Current column from 1 to WIDTH. Set to 0 by NEW command.
WIDTH:
  .space 1                                        // L5B64: Paper column width. Default value of 80.
TVPARS:
  .space 1                                        // L5B65: Number of inline parameters expected by RS232 (e.g. 2 for AT).
RASP:
  .space 1                                        // L5C38: Length of warning buzz.
PIP:
  .space 1                                        // L5C39: Length of keyboard click.
FLAGS:
  .space 1                                        // L5C3B: Flags to control the BASIC system:
                                                  //   Bit 0: 1=Suppress leading space.
                                                  //   Bit 1: 1=Using printer, 0=Using screen.
                                                  //   Bit 2: 1=Print in L-Mode, 0=Print in K-Mode.
                                                  //   Bit 3: 1=L-Mode, 0=K-Mode.
                                                  //   Bit 4: 1=128K Mode, 0=48K Mode. [Always 0 on 48K Spectrum].
                                                  //   Bit 5: 1=New key press code available in LAST_K.
                                                  //   Bit 6: 1=Numeric variable, 0=String variable.
                                                  //   Bit 7: 1=Line execution, 0=Syntax checking.
FLAGS2:
  .space 1                                        // L5C6A: Flags:
                                                  //   Bit 0  : 1=Screen requires clearing.
                                                  //   Bit 1  : 1=Printer buffer contains data.
                                                  //   Bit 2  : 1=In quotes.
                                                  //   Bit 3  : 1=CAPS LOCK on.
                                                  //   Bit 4  : 1=Using channel 'K'.
                                                  //   Bit 5-7: Not used (always 0).
FLAGS3:
  .space 1                                        // L5B66: Flags: [Name clashes with the ZX Interface 1 system variable at 0x5cb6]
                                                  //   Bit 0: 1=BASIC/Calculator mode, 0=Editor/Menu mode.
                                                  //   Bit 1: 1=Auto-run loaded BASIC program. [Set but never tested by the ROM]
                                                  //   Bit 2: 1=Editing RAM disk catalogue.
                                                  //   Bit 3: 1=Using RAM disk commands, 0=Using cassette commands.
                                                  //   Bit 4: 1=Indicate LOAD.
                                                  //   Bit 5: 1=Indicate SAVE.
                                                  //   Bit 6; 1=Indicate MERGE.
                                                  //   Bit 7: 1=Indicate VERIFY.
TV_FLAG:
  .space 1                                        // L5C3C: Flags associated with the TV:
                                                  //   Bit 0  : 1=Using lower editing area, 0=Using main screen.
                                                  //   Bit 1-2: Not used (always 0).
                                                  //   Bit 3  : 1=Mode might have changed.
                                                  //   Bit 4  : 1=Automatic listing in main screen, 0=Ordinary listing in main screen.
                                                  //   Bit 5  : 1=Lower screen requires clearing after a key press.
                                                  //   Bit 6  : 1=Tape Loader option selected (set but never tested). [Always 0 on 48K Spectrum]
                                                  //   Bit 7  : Not used (always 0).
BORDCR:
  .space 1                                        // L5C48: Border colour multiplied by 8; also contains the attributes normally used for the lower half.
ERR_NR:
  .space 1                                        // L5C3A: 1 less than the report code. Starts off at 255 (for -1).
DF_SZ:
  .space 1                                        // L5C6B: The number of lines (including one blank line) in the lower part of the screen. (1-60)
SCR_CT:
  .space 1                                        // L5C8C: Counts scrolls - it is always 1 more than the number of scrolls that will be done before
                                                  // stopping with 'scroll?'.
P_POSN_X:
  .space 1                                        // L5C7F: 109-column number of printer position.
ECHO_E_X:
  .space 1                                        // L5C82: 109-column number (in lower half) of end of input buffer.
ECHO_E_Y:
  .space 1                                        // L5C83: 60-line number (in lower half) of end of input buffer.
S_POSN_X:
  .space 1                                        // L5C88: 109-column number for PRINT position.
S_POSN_Y:
  .space 1                                        // L5C89: 60-line number for PRINT position.
S_POSN_X_L:
  .space 1                                        // L5C8A: Like S_POSN_X for lower part.
S_POSN_Y_L:
  .space 1                                        // L5C8B: Like S_POSN_Y for lower part.
P_FLAG:
  .space 1                                        // L5C91: Flags:
                                                  //   Bit 0: Temporary 1=OVER 1, 0=OVER 0.
                                                  //   Bit 1: Permanent 1=OVER 1, 0=OVER 0.
                                                  //   Bit 2: Temporary 1=INVERSE 1, 0=INVERSE 0.
                                                  //   Bit 3: Permanent 1=INVERSE 1, 0=INVERSE 0.
                                                  //   Bit 4: Temporary 1=Using INK 9.
                                                  //   Bit 5: Permanent 1=Using INK 9.
                                                  //   Bit 6: Temporary 1=Using PAPER 9.
                                                  //   Bit 7: Permanent 1=Using PAPER 9.
BREG:
  .space 1                                        // L5C67: Calculator's B register.
ATTR_P:
  .space 1                                        // L5C8D: Permanent current colours, etc, as set up by colour statements.
MASK_P:
  .space 1                                        // L5C8E: Used for transparent colours, etc. Any bit that is 1 takes value from current attribute value, 0 from ATTR_P/T.
ATTR_T:
  .space 1                                        // L5C8F: Temporary current colours (as set up by colour items).
MASK_T:
  .space 1                                        // L5C90: Like MASK_P, but temporary.
MODE:
  .space 1                                        // L5C41: Specifies cursor type:
                                                  //   0x00='L' or 'C'.
                                                  //   0x01='E'.
                                                  //   0x02='G'.
                                                  //   0x04='K'.
LASTK:
  .space 1                                        // L5C08: Last key press. Read by wait_key_press when FLAGS bit 5 is set.


// --------------------------
// Editor Workspace Variables
// --------------------------
// These occupy addresses 0xec00-0xffff in physical RAM bank 7, and form a workspace used by 128 BASIC Editor.
//
EC00:
  .space 3                                        // Byte 0: Flags used when inserting a line into the BASIC program (first 4 bits are mutually exclusive).
                                                  //   Bit 0: 1=First row of the BASIC line off top of screen.
                                                  //   Bit 1: 1=On first row of the BASIC line.
                                                  //   Bit 2: 1=Using lower screen and only first row of the BASIC line visible.
                                                  //   Bit 3: 1=At the end of the last row of the BASIC line.
                                                  //   Bit 4: Not used (always 0).
                                                  //   Bit 5: Not used (always 0).
                                                  //   Bit 6: Not used (always 0).
                                                  //   Bit 7: 1=Column with cursor not yet found.
                                                  // Byte 1: Column number of current position within the BASIC line being inserted. Used when fetching characters.
                                                  // Byte 2: Row number of current position within the BASIC line is being inserted. Used when fetching characters.
EC03:
  .space 3                                        // Byte 0: Flags used upon an error when inserting a line into the BASIC program (first 4 bits are mutually exclusive).
                                                  //   Bit 0: 1=First row of the BASIC line off top of screen.
                                                  //   Bit 1: 1=On first row of the BASIC line.
                                                  //   Bit 2: 1=Using lower screen and only first row of the BASIC line visible.
                                                  //   Bit 3: 1=At the end of the last row of the BASIC line.
                                                  //   Bit 4: Not used (always 0).
                                                  //   Bit 5: Not used (always 0).
                                                  //   Bit 6: Not used (always 0).
                                                  //   Bit 7: 1=Column with cursor not yet found.
                                                  // Byte 1: Start column number where BASIC line is being entered. Always holds 0.
                                                  // Byte 2: Start row number where BASIC line is being entered.
EC0C:
  .space 1                                        // Current menu index.
EC0D:
  .space 1                                        // Flags used by 128 BASIC Editor:
                                                  //   Bit 0: 1=Screen Line Edit Buffer (including Below-Screen Line Edit Buffer) is full.
                                                  //   Bit 1: 1=Menu is displayed.
                                                  //   Bit 2: 1=Using RAM disk.
                                                  //   Bit 3: 1=Current line has been altered.
                                                  //   Bit 4: 1=Return to calculator, 0=Return to main menu.
                                                  //   Bit 5: 1=Do not process the BASIC line (used by the Calculator).
                                                  //   Bit 6: 1=Editing area is the lower screen, 0=Editing area is the main screen.
                                                  //   Bit 7: 1=Waiting for key press, 0=Got key press.
EC0E:
  .space 1                                        // Mode:
                                                  //   0x00 = Edit Menu mode.
                                                  //   0x04 = Calculator mode.
                                                  //   0x07 = Tape Loader mode. [Effectively not used as overwritten by 0xff]
                                                  //   0xff = Tape Loader mode.
EC0F:
  .space 1                                        // Main screen colours used by the 128 BASIC Editor - alternate ATTR_P.
EC10:
  .space 1                                        // Main screen colours used by the 128 BASIC Editor - alternate MASK_P.
EC11:
  .space 1                                        // Temporary screen colours used by the 128 BASIC Editor - alternate ATTR_T.
EC12:
  .space 1                                        // Temporary screen colours used by the 128 BASIC Editor - alternate MASK_T.
EC13:
  .space 1                                        // Temporary store for P_FLAG:
                                                  //   Bit 0: 1=OVER 1, 0=OVER 0.
                                                  //   Bit 1: Not used (always 0).
                                                  //   Bit 2: 1=INVERSE 1, INVERSE 0.
                                                  //   Bit 3: Not used (always 0).
                                                  //   Bit 4: 1=Using INK 9.
                                                  //   Bit 5: Not used (always 0).
                                                  //   Bit 6: 1=Using PAPER 9.
                                                  //   Bit 7: Not used (always 0).
EC14:
  .space 1                                        // Not used.
EC15:
  .space 1                                        // Holds the number of editing lines: 20 for the main screen, 1 for the lower screen.


// 0xec16  735   Screen Line Edit Buffer. This represents the text on screen that can be edited. It holds 21 rows,
//              with each row consisting of 32 characters followed by 3 data bytes. Areas of white
//              space that do not contain any editable characters (e.g. the indent that starts subsequent
//              rows of a BASIC line) contain the value 0x00.
//                Data Byte 0:
//                  Bit 0: 1=The first row of the BASIC line.
//                  Bit 1: 1=Spans onto next row.
//                  Bit 2: Not used (always 0).
//                  Bit 3: 1=The last row of the BASIC line.
//                  Bit 4: 1=Associated line number stored.
//                  Bit 5: Not used (always 0).
//                  Bit 6: Not used (always 0).
//                  Bit 7: Not used (always 0).
//                Data Bytes 1-2: Line number of corresponding BASIC line (stored for the first row of the BASIC line only, holds 0x0000).
// 0xeef5    1   Flags used when listing the BASIC program:
//                Bit 0   : 0=Not on the current line, 1=On the current line.
//                Bit 1   : 0=Previously found the current line, 1=Not yet found the current line.
//                Bit 2   : 0=Enable display file updates, 1=Disable display file updates.
//                Bits 3-7: Not used (always 0).
// 0xeef6    1   Store for temporarily saving the value of TV_FLAG.
// 0xeef7    1   Store for temporarily saving the value of COORDS.
// 0xeef9    1   Store for temporarily saving the value of P_POSN_X.
// 0xeefa    2   Store for temporarily saving the value of PR_CC.
// 0xeefc    1   Store for temporarily saving the value of ECHO_E_X.
// 0xeefd    1   Store for temporarily saving the value of ECHO_E_Y.
// 0xeefe    2   Store for temporarily saving the value of DF_CC.


// something not quite right here - we need two bytes for DF_CC_L, but the comments claim that S_POSN_X is stored at 0xef01
// 0xef00    2   Store for temporarily saving the value of DF_CC_L.


// 0xef01    1   Store for temporarily saving the value of S_POSN_X.
// 0xef02    1   Store for temporarily saving the value of S_POSN_Y.
// 0xef03    1   Store for temporarily saving the value of S_POSN_X_L.
// 0xef04    1   Store for temporarily saving the value of S_POSN_Y_L.
// 0xef05    1   Store for temporarily saving the value of SCR_CT.
// 0xef06    1   Store for temporarily saving the value of ATTR_P.
// 0xef07    1   Store for temporarily saving the value of MASK_P.
// 0xef08    1   Store for temporarily saving the value of ATTR_T.
// 0xef09 1512   Used to store screen area (12 rows of 14 columns) where menu will be shown.
//              The rows are stored one after the other, with each row consisting of the following:
//                - 8 lines of 14 display file bytes.
//                - 14 attribute file bytes.
// 0xf4f1-0xf6e9  Not used. 505 bytes.
// 0xf6f4    1   Flags used when deleting:
//                Bit 0   : 1=Deleting on last row of the BASIC line, 0=Deleting on row other than the last row of the BASIC line.
//                Bits 1-7: Not used (always 0).
// 0xf6f5    1   Number of rows held in the Below-Screen Line Edit Buffer.
// 0xf6f6    2   Intended to point to the next location to access within the Below-Screen Line Edit Buffer, but incorrectly initialised to 0x0000 by the routine at 0x30d6 (ROM 0) and then never used.
// 0xf6f8  735   Below-Screen Line Edit Buffer. Holds the remainder of a BASIC line that has overflowed off the bottom of the Screen Line Edit Buffer. It can hold 21 rows, with each row
//              consisting of 32 characters followed by 3 data bytes. Areas of white space that do not contain any editable characters (e.g. the indent that starts subsequent rows of a BASIC line)
//              contain the value 0x00.
//                Data Byte 0:
//                  Bit 0: 1=The first row of the BASIC line.
//                  Bit 1: 1=Spans onto next row.
//                  Bit 2: Not used (always 0).
//                  Bit 3: 1=The last row of the BASIC line.
//                  Bit 4: 1=Associated line number stored.
//                  Bit 5: Not used (always 0).
//                  Bit 6: Not used (always 0).
//                  Bit 7: Not used (always 0).
//                Data Bytes 1-2: Line number of corresponding BASIC line (stored for the first row of the BASIC line only, holds 0x0000).
// 0xf9d7    2   Line number of the BASIC line in the program area being edited (or 0x0000 for no line).
// 0xf9db    1   Number of rows held in the Above-Screen Line Edit Buffer.
// 0xf9dc    2   Points to the next location to access within the Above-Screen Line Edit Buffer.
// 0xf9de  700   Above-Screen Line Edit Buffer. Holds the rows of a BASIC line that has overflowed off the top of the Screen Line Edit Buffer.
//              It can hold 20 rows, with each row consisting of 32 characters followed by 3 data bytes. Areas of white space that do not
//              contain any editable characters (e.g. the indent that starts subsequent rows of a BASIC line) contain the value 0x00.
//                Data Byte 0:
//                  Bit 0: 1=The first row of the BASIC line.
//                  Bit 1: 1=Spans onto next row.
//                  Bit 2: Not used (always 0).
//                  Bit 3: 1=The last row of the BASIC line.
//                  Bit 4: 1=Associated line number stored.
//                  Bit 5: Not used (always 0).
//                  Bit 6: Not used (always 0).
//                  Bit 7: Not used (always 0).
//                Data Bytes 1-2: Line number of corresponding BASIC line (stored for the first row of the BASIC line only, holds 0x0000).
// 0xfc9e    1   0x00=Print a leading space when constructing keyword.
// 0xfc9f    2   Address of the next character to fetch within the BASIC line in the program area, or 0x0000 for no next character.
// 0xfca1    2   Address of the next character to fetch from the Keyword Construction Buffer, or 0x0000 for no next character.
// 0xfca3   11   Keyword Construction Buffer. Holds either a line number or keyword string representation.
// 0xfcae-0xfcfc  Construct a BASIC Line routine.                       <<< RAM routine - See end of file for description >>>
// 0xfcfd-0xfd2d  Copy String Into Keyword Construction Buffer routine. <<< RAM routine - See end of file for description >>>
// 0xfd2e-0xfd69  Identify Character Code of Token String routine.      <<< RAM routine - See end of file for description >>>
// 0xfd74    9   The Keyword Conversion Buffer holding text to examine to see if it is a keyword.
// 0xfd7d    2   Address of next available location within the Keyword Conversion Buffer.
// 0xfd7f    2   Address of the space character between words in the Keyword Conversion Buffer.
// 0xfd81    1   Keyword Conversion Buffer flags, used when tokenizing a BASIC line:
//                Bit 0   : 1=Buffer contains characters.
//                Bit 1   : 1=Indicates within quotes.
//                Bit 2   : 1=Indicates within a REM.
//                Bits 3-7: Not used (always reset to 0).
// 0xfd82    2   Address of the position to insert the next character within the BASIC line workspace. The BASIC line
//              is created at the spare space pointed to by E_LINE.
// 0xfd84    1   BASIC line insertion flags, used when inserting a characters into the BASIC line workspace:
//                Bit 0   : 1=The last character was a token.
//                Bit 1   : 1=The last character was a space.
//                Bits 2-7: Not used (always 0).
// 0xfd85    2   Count of the number of characters in the typed BASIC line being inserted.
// 0xfd87    2   Count of the number of characters in the tokenized version of the BASIC line being inserted.
// 0xfd89    1   Holds '<' or '>' if this was the previously examined character during tokenization of a BASIC line, else 0x00.
// 0xfd8a    1   Locate Error Marker flag, holding 0x01 is a syntax error was detected on the BASIC line being inserted and the equivalent position within
//              the typed BASIC line needs to be found with, else it holds 0x00 when tokenizing a BASIC line.
// 0xfd8b    2   Stores the stack pointer for restoration upon an insertion error into the BASIC line workspace.
// 0xfd8c-0xff23  Not used. 408 bytes.
// 0xff24    2   Never used. An attempt is made to set it to 0xec00. This is a remnant from the Spanish 128, which stored the address of the Screen Buffer here.
//              The value is written to RAM bank 0 instead of RAM bank 7, and the value never subsequently accessed.
// 0xff26    2   Not used.
// 0xff28-0xff60  Not used. On the Spanish 128 this memory holds a routine that copies a character into the display file. The code to copy to routine into RAM,
//              and the routine itself are present in ROM 0 but are never executed. <<< RAM routine - See end of file for description >>>
// 0xff61-0xffff  Not used. 159 bytes.


.align 1


// Editor workspace variables
FC9A:
  .space 2                                        // The line number at the top of the screen, or 0x0000 for the first line.
REPDEL:
  .space 1                                        // L5C09: Place REPDEL in .align 1 section since REPDEL+REPPER is read/written together as a halfword.
                                                  // Time (in 50ths of a second) that a key must be held down before it repeats. This starts off at 35.
REPPER:
  .space 1                                        // L5C0A: Delay (in 50ths of a second) between successive repeats of a key held down - initially 5.
E_PPC:
  .space 1                                        // L5C49: Number of current line (with program cursor) (low).
E_PPC_hi:
  .space 1                                        // L5C4A: Number of current line (with program cursor) (high).
BAUD:
  .space 2                                        // L5B5F: Baud rate timing constant for RS232 socket. Default value of 11. [Name clash with ZX Interface 1 system variable at 0x5cc3]
SERFL:
  .space 2                                        // L5B61:
                                                  //   Byte 0: Second character received flag:
                                                  //     Bit 0   : 1=Character in buffer.
                                                  //     Bits 1-7: Not used (always hold 0).
                                                  //   Byte 1: Received Character.
RNFIRST:
  .space 2                                        // L5B94: Starting line number when renumbering. Default value of 10.
RNSTEP:
  .space 2                                        // L5B96: Step size when renumbering. Default value of 10.
STRMS:
  .space 2*19                                     // L5C10: Address offsets of 19 channels attached to streams.
TVDATA:
  .space 2                                        // L5C0E: Stores bytes of colour, AT and TAB controls going to TV.
EC06:
  .space 2                                        // Count of the number of editable characters in the BASIC line up to the cursor within the Screen Line Edit Buffer.
EC08:
  .space 2                                        // Version of E_PPC used by BASIC Editor to hold last line number entered.
// F6F2/F6F3 accessed together
F6F2:
  .space 1                                        // Edit area info - Bottom row threshold for scrolling down.
F6F3:
  .space 1                                        // Edit area info - Number of rows in the editing area.
// FD6A/FD6B accessed together
FD6A:
  .space 1                                        // Flags used when shifting BASIC lines within edit buffer rows [Redundant]:
                                                  //   Bit 0  : 1=Set to 1 but never reset or tested. Possibly intended to indicate the start of a new BASIC line and hence whether indentation required.
                                                  //   Bit 1-7: Not used (always 0).
FD6B:
  .space 1                                        // The number of characters to indent subsequent rows of a BASIC line by.


.align 2
// F6EE/F6EF/F6F0/F6F1 accessed together
F6EE:
  .space 1                                        // Cursor position info - Current row number.
F6EF:
  .space 1                                        // Cursor position info - Current column number.
F6F0:
  .space 1                                        // Cursor position info - Preferred column number. Holds the last user selected column position. The Editor will attempt to
                                                  // place the cursor on this column when the user moves up or down to a new line.
F6F1:
  .space 1                                        // Edit area info - Top row threshold for scrolling up.
KSTATE:
  .space 4                                        // L5C00: 4-byte keyboard state block. Used by handle_keyboard_input (xhci.s), k_new / k_end / k_repeat / keyboard (roms/).
                                                  //   +0: held HID scancode (0 = no key held; scancode 0 is reserved so safe as sentinel).
                                                  //   +1: unused on spectrum4 (Z80 used this for the 5-frame debounce counter; USB firmware debounces so we don't need it).
                                                  //   +2: REPDEL / REPPER frame countdown.
                                                  //   +3: cached terminal code for k_repeat to re-deliver.
COORDS_X:
  .space 2                                        // L5C7D: X-coordinate of last point plotted.
COORDS_Y:
  .space 2                                        // L5C7E: Y-coordinate of last point plotted.


.align 3


// All 8 bytes updated together in one str instruction, so align 3 here
FD6C:
  .space 1                                        // Cursor settings (indexed by IX+0x00) - initialised to 0x00, but never used.
FD6D:
  .space 1                                        // Cursor settings (indexed by IX+0x01) - number of rows above the editing area.
FD6E:
  .space 1                                        // Cursor settings (indexed by IX+0x02) - initialised to 0x00 (when using lower screen) or 0x14 (when using main screen), but never subsequently used.
FD6F:
  .space 1                                        // Cursor settings (indexed by IX+0x03) - initialised to 0x00, but never subsequently used.
FD70:
  .space 1                                        // Cursor settings (indexed by IX+0x04) - initialised to 0x00, but never subsequently used.
FD71:
  .space 1                                        // Cursor settings (indexed by IX+0x05) - initialised to 0x00, but never subsequently used.
FD72:
  .space 1                                        // Cursor settings (indexed by IX+0x06) - attribute colour.
FD73:
  .space 1                                        // Cursor settings (indexed by IX+0x07) - screen attribute where cursor is displayed.


SFNEXT:
  .space 8                                        // L5B83: End of RAM disk catalogue marker. Pointer to first empty catalogue entry.
SFSPACE:
  .space 8                                        // L5B85: Number of bytes free in RAM disk.
CHARS:
  .space 8                                        // L5C36: 256 less than address of character set, which starts with ' ' and carries on to '©'.
LIST_SP:
  .space 8                                        // Address of return address from automatic listing.


next_interrupt:
  .space 8


// Pointers to inside the HEAP
VARS:
  .space 8                                        // L5C4B: Address of variables.
// DEST:          .space 8                         // Address of variable in assignment.
CHANS:
  .space 8                                        // L5C4F: Address of channel data.
CURCHL:
  .space 8                                        // L5C51: Address of information currently being used for input and output.
PROG:
  .space 8                                        // L5C53: Address of BASIC program.
// NXTLIN:        .space 8                         // Address of next line in program.
DATADD:
  .space 8                                        // L5C57: Address of terminator of last DATA item.
E_LINE:
  .space 8                                        // L5C59: Address of command being typed in.
// K_CUR:         .space 8                         // Address of cursor.
CH_ADD:
  .space 8                                        // L5C5D: Address of the next character to be interpreted - the character after the argument of PEEK,
                                                  // or the NEWLINE at the end of a POKE statement.
X_PTR:
  .space 8                                        // L5C5F: Address of the character after the '?' marker.
WORKSP:
  .space 8                                        // L5C61: Address of temporary work space.
STKBOT:
  .space 8                                        // L5C63: Address of bottom of calculator stack.
STKEND:
  .space 8                                        // L5C65: Address of start of spare space.


// Other pointers
// TARGET:        .space 8                         // L5B58: Address of subroutine to call in ROM 1.
RAMTOP:
  .space 8                                        // L5CB2: Address of last byte of BASIC system area.
P_RAMT:
  .space 8                                        // L5CB4: Address of last byte of physical RAM.
UDG:
  .space 8                                        // L5C7B: Address of first user-defined graphic. Can be changed to save space by having fewer.
ERR_SP:
  .space 8                                        // L5C3D: Address of item on machine stack to be used as error return.


// Editor
// OLDSP:         .space 8                         // Stores old stack pointer when TSTACK in use.
DF_CC:
  .space 8                                        // L5C84: Address in display file of PRINT position.
DF_CC_L:
  .space 8                                        // L5C86: Like DF CC for lower part of screen.
PR_CC:
  .space 8                                        // L5C80: Full address of next position for LPRINT to print at (in ZX Printer buffer).
K_CUR:
  .space 8                                        // L5C5B: Address of cursor.
                                                  // Legal values in printer_buffer range. [Not used in 128K mode]


F6EA:
  .space 8                                        // The jump table address for the current menu.
F6EC:
  .space 8                                        // The text table address for the current menu.


MEMBOT:
  .space 32                                       // L5C92: Calculator's memory area - used to store numbers that cannot conveniently be put on the
                                                  // calculator stack.


.align 4
// TSTACK:        .space 0x400
// TSTACK_end:


// Generic timer ticks per 20ms frame (cntfrq / 50), populated by timer_init.
// Not a Spectrum sysvar: no trailing // on .space line keeps sysvars.sh from picking it up.
timer_period:
  .space 4


.align 4                                          // Ensure sysvars_end is at a 16 byte boundary.
sysvars_end:


printer_buffer:
  .space 0xd80                                    // Printer buffer used by 48K Basic but not by 128K Basic (see docs/printer-buffer.md)
printer_buffer_end:


// Memory regions
display_file:
  .space (SCREEN_HEIGHT-BORDER_TOP-BORDER_BOTTOM)*(SCREEN_WIDTH-BORDER_LEFT-BORDER_RIGHT)/8
                                         // L4000
                                                  // One pixel per bit => 8 pixels per byte
display_file_end:


attributes_file:
  .space (SCREEN_HEIGHT-BORDER_TOP-BORDER_BOTTOM)*(SCREEN_WIDTH-BORDER_LEFT-BORDER_RIGHT)/256
                                         // L5800
                                                  // 16*16 pixels per attribute record => 256 pixles per byte
attributes_file_end:


.section bss_userheap, "aw", %nobits


ram_disk:
  .space RAM_DISK_SIZE
heap:
  .space HEAP_SIZE




.section bss_coherent, "aw", %nobits


// 21 is 2MB boundary, which matches granularity of our MMU page tables.
// This is needed since memory attributes are different for this memory region.
.align 21
coherent_start:


.align 12
xhci_start:
scratchpad_bufs:
  .space 31 * 0x1000                              // 31 scratchpads


.align 12                                         // technically only need .align 4 but since it comes straight after scratchpad_bufs
                                                  // we get .align 12 for free allowing us to use adrp without needing extra add :lo12:
dcbaa:
  .space 33 * 0x8                                 // 33 entries


.align 6
scratchpad_ptrs:
  .space 31 * 0x8                                 // 31 entries


.align 12
command_ring:
  .space 0x100 * 0x10                             // 256 entries
command_ring_end:


.align 12
event_ring:
  .space 0xfc * 0x10                              // 252 entries (so that ERST can fit in same page)
event_ring_end:


.align 6                                          // Needs to be 64 byte aligned since ERSTBA bits 0-5 are RsvdP
erst:
  .space 0x40                                     // only the first 0x10 bytes matter, but reserve 0x40 since spec says:
                                                  // The Ring Segment Size may be set to any value from 16 to 4096, however
                                                  // software shall allocate a buffer for the Event Ring Segment that rounds up its
                                                  // size to the nearest 64B boundary to allow full cache-line accesses.


.align 12                                         // Technically only requires .align 6 but sits at page boundary anyway, and this way
                                                  // adrp can be used.
slot1_device_context:
  .space 0x80                                     // 1 Slot Context and 3 Endpoint Contexts; EP0, EP1 OUT, EP1 IN (i.e. 4 contexts, each 0x20 bytes = 4 * 0x20 = 0x80 bytes)
slot1_descriptor:
  .space 0x80                                     // reusable descriptor buffer (device, configuration, hub class)


.align 6
slot1_input_context:
  .space 0xa0                                     // Input Control (0x20) + Slot (0x20) + EP0 (0x20) + EP1 OUT (0x20) + EP1 IN (0x20)


.align 6
slot2_device_context:
  .space 0x80                                     // Slot + Endpoint contexts for keyboard (4 contexts, each 0x20)


.align 6
slot2_input_context:
  .space 0xa0                                     // Input Control (0x20) + Slot (0x20) + EP0 (0x20) + EP1 OUT (0x20) + EP1 IN (0x20)
keyboard_report:
  .space 0x08                                     // 8-byte HID boot protocol report buffer


.align 4                                          // 16-byte boundary for transfer ring segments [XHCI] s4.11.5.1 p228
transfer_ring_slot1_EP0:
  .space 0x20 * 0x10                              // 32 entries
transfer_ring_slot1_EP0_end:
transfer_ring_slot1_EP1:
  .space 0x20 * 0x10                              // 32 entries
transfer_ring_slot1_EP1_end:
transfer_ring_slot2_EP0:
  .space 0x20 * 0x10                              // 32 entries
transfer_ring_slot2_EP0_end:
transfer_ring_slot2_EP1:
  .space 0x20 * 0x10                              // 32 entries (interrupt IN)
transfer_ring_slot2_EP1_end:


.align 12
xhci_end:


.align 21
coherent_end:










